package io.github.finalparadox.client;
import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import io.github.finalparadox.entity.RuinPillarEntity;import net.minecraft.client.renderer.MultiBufferSource;import net.minecraft.client.renderer.block.BlockRenderDispatcher;import net.minecraft.client.renderer.entity.EntityRenderer;import net.minecraft.client.renderer.entity.EntityRendererProvider;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.inventory.InventoryMenu;import net.minecraft.world.level.block.Blocks;
public final class RuinPillarRenderer extends EntityRenderer<RuinPillarEntity>{private final BlockRenderDispatcher blocks;public RuinPillarRenderer(EntityRendererProvider.Context c){super(c);blocks=c.getBlockRenderDispatcher();shadowRadius=.4F;}@Override public ResourceLocation getTextureLocation(RuinPillarEntity e){return InventoryMenu.BLOCK_ATLAS;}@Override public void render(RuinPillarEntity e,float y,float p,PoseStack pose,MultiBufferSource b,int l){pose.pushPose();pose.mulPose(Axis.YP.rotationDegrees(-e.getYRot()));pose.mulPose(Axis.XP.rotationDegrees(20));for(int i=0;i<4;i++){pose.pushPose();pose.translate(-.3125,i*.6,-.3125);pose.scale(.625F,.625F,.625F);blocks.renderSingleBlock(Blocks.LODESTONE.defaultBlockState(),pose,b,l,OverlayTexture.NO_OVERLAY);pose.popPose();}pose.popPose();super.render(e,y,p,pose,b,l);}}
